const XP_PER_LEVEL = 50;
// Keyed by ENEMY_KINDS id, not by display name: the rank and file are given
// personal names at spawn, so a name is no longer a stable identity.
const XP_ON_KILL = { brigand: 30, rogue: 36, brute: 50,
  thief: 40, attackdog: 26, knight: 48, archerknight: 40, priest: 46, elder: 50, paladin: 160,
  warlord: 120 };
// Clearing the field is worth more than the sum of its parts, so a full party
// still makes real progress rather than a fifth of a level.
function victoryXp(foes) {
  return 25 + foes * 10;
}
function killXp(u) {
  return XP_ON_KILL[u.kind] || 20;
}

// Tiles are 32px of art at 1.5 screen px per texel, so a tile is 48px across.
const TILE = 48;
const GAP = 3;
const PAD = 6;
const STEP = TILE + GAP;
function boardDims() {
  const innerW = COLS * STEP - GAP;
  const innerH = ROWS * STEP - GAP;
  return {
    innerW,
    innerH,
    outerW: innerW + PAD * 2,
    outerH: innerH + PAD * 2,
    wrapper: Math.max(innerW + PAD * 2, innerH + PAD * 2) + 20,
  };
}

