// An icon for every item, chosen from what the item is -- the power its weapon
// runs on, the weight of its armour, the slot it fills -- so a new item is never
// iconless and no per-item list has to be kept in step.
const ITEM_ICONS = {
  str: Sword, dex: Crosshair, mag: Sparkles,
  heavy: ShieldCheck, medium: ShieldHalf, light: ShieldAlert, robe: Feather,
  "Left Hand": Shield, Head: Crown, Accessory: Star, Trophy: Skull, potion: FlaskConical,
};
function itemIcon(it) {
  if (!it) return Package;
  if (it.weight) return ITEM_ICONS[it.weight] || Package;
  if (it.slot === "Right Hand") return ITEM_ICONS[it.scales] || Sword;
  return ITEM_ICONS[it.slot] || Package;
}

// Every icon a skill node may claim, by name. Nodes carry the name, not the
// component, so the trees stay pure data and an unknown name falls back rather
// than rendering nothing at all.
