function Portrait({ classKey, name, sprite, size }) {
  // The art is 44x40, so a square box would squash it.
  const w = Math.round(size * 44 / 40);
  return (
    <img
      src={spriteFor(classKey, "front", name, sprite)}
      alt={classKey}
      draggable={false}
      style={{
        width: w,
        height: size,
        maxWidth: "none",
        minWidth: w,
        display: "block",
        imageRendering: "pixelated",
      }}
    />
  );
}

const DIR_VEC = { N: { dx: 0, dy: -1 }, S: { dx: 0, dy: 1 }, E: { dx: 1, dy: 0 }, W: { dx: -1, dy: 0 } };
const SLOT_KEYS = ["rightHand", "leftHand", "head", "armor", "accessory"];
const SLOT_LABELS = {
  rightHand: "Right Hand",
  leftHand: "Left Hand",
  head: "Head",
  armor: "Armor",
  accessory: "Accessory",
};
// The same slots named for a narrow column, where the full words do not fit
// and the browser would cut one mid-word. Read through SLOT_LABELS, so a new
// slot needs no second entry unless its name is long.
const SLOT_SHORT = { rightHand: "RH", leftHand: "LH", accessory: "Acc" };
const slotShort = (k) => SLOT_SHORT[k] || SLOT_LABELS[k];

