  // they own no tree, hold no equipment, and can never be recruited -- but a
  // summon fights on the player's team, so `team` and `class` stay separate
  // ideas everywhere.
  Hound: { sprite: "dog", scales: "str" },
  ArcherKnight: { sprite: "archerknight_m", spriteF: "archerknight_f", scales: "dex" },
  GreatBear: { sprite: "bear", scales: "str" },
