  ward: {
    label: "Ward", aura: { span: 1, status: "warded", skipSelf: true },
    detail: "+10% DEF / 10% dodge to adjacent allies.",
  },
  wintersgrip: {
    label: "Winter's Grip",
    detail: "Ice spells freeze water and convert land tiles to snow for three turns.",
  },
