// Does this unit own a passive that sets the given flag?
function hasFlag(u, flag) {
  // A unit may carry a flag outright. Enemies have no skill tree to unlock one
  // from, so this is how a thief gets Pathfinder without inventing a parallel
  // mechanism for it.
  if (u.flags && u.flags.includes(flag)) return true;
  return treeFor(u.class).some(
    (n) => n.kind === "passive" && n.flag === flag && nodeUnlocked(u, n.id)
  );
}

// --- Blast shapes --------------------------------------------------------
// The footprint an area skill covers. One function answers for all of them, so
// a new shape is a row here rather than another nested loop at every site that
// needs to know what a spell touches: the highlight, the resolution and the AI.
const SHAPES = {
  single: { label: "a single tile", tiles: (c) => [c] },
  plus: {
    label: "a tile and its four neighbours",
    tiles: (c) => [c, { x: c.x + 1, y: c.y }, { x: c.x - 1, y: c.y }, { x: c.x, y: c.y + 1 }, { x: c.x, y: c.y - 1 }],
  },
  diamond: {
    label: "everything within two tiles",
    tiles: (c) => ringTiles(c, 0, 2),
  },
  wide: {
    label: "everything within three tiles",
    tiles: (c) => ringTiles(c, 0, 3),
  },
  ring: {
    label: "a hollow ring two tiles across",
    tiles: (c) => ringTiles(c, 2, 2),
  },
  adjacent: {
    label: "the four adjacent tiles",
    tiles: (c) => ringTiles(c, 1, 1),
  },
  crosswall: {
    label: "five tiles athwart the caster's line, centred on the target",
    tiles: (c, from) => {
      if (!from) return [c];
      const v = DIR_VEC[directionTo(from, c)];
      // A quarter turn: what ran away from the caster now runs across them.
      const across = { dx: -v.dy, dy: v.dx };
      const out = [];
      for (let i = -2; i <= 2; i++)
        out.push({ x: c.x + across.dx * i, y: c.y + across.dy * i });
      return out;
    },
  },
  line: {
    label: "a line driven out from the caster",
    tiles: (c, from) => {
      if (!from) return [c];
      const dir = directionTo(from, c);
      const v = DIR_VEC[dir];
      const out = [];
      const len = Math.max(1, manhattan(from, c));
      for (let i = 1; i <= len; i++) out.push({ x: from.x + v.dx * i, y: from.y + v.dy * i });
      return out;
    },
  },
};
// Every tile whose distance from the centre falls between two bounds.
function ringTiles(c, min, max) {
  const out = [];
  for (let dx = -max; dx <= max; dx++)
    for (let dy = -max; dy <= max; dy++) {
      const d = Math.abs(dx) + Math.abs(dy);
      if (d >= min && d <= max) out.push({ x: c.x + dx, y: c.y + dy });
    }
  return out;
}
// The tiles a blast actually covers, clipped to the board and deduplicated.
// Where a blast is centred: the tile picked, or the caster themselves for a
// working that takes no target. The highlight and the blow both ask here, so
// they cannot disagree -- and they did. A self-centred spin set no `cx`, so
// the preview drew nothing and Whirlwind was swung blind.
// The tiles a working actually covers. A trap is laid on the one tile it is
// aimed at -- the executor has always known that, but the highlight asked the
// shape registry, which defaults to a cross, and drew five tiles for a trap
// set on one. Both ask here now.
// The workings that cover ground whether or not they name a shape. Everything
// else lands on the tile it is aimed at.
const SPREADING_TYPES = ["aoe", "storm", "wall"];
// Whether a working reaches a given fighter at all: the ground it covers, and
// then whose side it spares. A blast says `foesOnly`; a shout says `foes` or
// `everyone`, and otherwise means allies. Three spellings of one question,
// answered here so the panel, the highlight and the blow cannot disagree.
// The kinds that hand something out rather than take it. A blast asks whether
// it wounds by declaring `noDamage`; these never wound whatever they declare,
// and the forecast has to know it or it invents numbers for a shout.
const GIVING_TYPES = ["bestow", "mend", "revive", "summon"];
function dealsHarm(ab) {
  return !!ab && !ab.noDamage && !GIVING_TYPES.includes(ab.type);
}
function abilityTouches(ab, caster, v) {
  if (!ab || !v || !v.alive || !caster) return false;
  if (!blastCatches(ab, v)) return false;
  if (ab.everyone) return true;
  if (ab.foes || ab.foesOnly) return v.team !== caster.team;
  if (ab.type === "bestow" || ab.type === "mend") return v.team === caster.team;
  return true;
}
function abilityFootprint(ab, center, unit) {
  if (!ab || !center) return [];
  // A trap is laid on the one tile it is aimed at whatever its shape says.
  // Everything else carries the shape `expandNode` gave it, which is a cross
  // only for the kinds that spread.
  if (ab.type === "trap") return [center];
  // A shout covers ground the same way a blast does. `burst` and `shape` were
  // two separate answers to "who does this touch", so anything taught to one --
  // a footprint, a highlight, a forecast -- had to be taught again to the
  // other. One answer now, and a working that bursts is asked here like the
  // rest.
  if (ab.burst) return ringTiles(center, 0, ab.burst);
  return shapeTiles(ab.shape, center, unit);
}
function abilityCenter(ab, pending, unit) {
  if (pending && pending.cx != null) return { x: pending.cx, y: pending.cy };
  if (ab && ab.target === "self" && unit) return { x: unit.x, y: unit.y };
  return null;
}
// Who a blast passes over. Standing in water is proof against fire, whoever
// throws it -- the targeting already refused to aim fire at water, but a blast
// centred on dry land washed over anyone standing in it, and the forecast and
// the blow both counted them. Asked here, so the two cannot differ.
function blastCatches(ab, v) {
  if (!v || !v.alive) return false;
  if (ab && ab.fire && isWater(v.x, v.y)) return false;
  return true;
}
function shapeTiles(shape, center, from) {
  const def = SHAPES[shape] || SHAPES.plus;
  const seen = new Set();
  return def.tiles(center, from).filter((t) => {
    const k = key(t.x, t.y);
    if (t.x < 0 || t.y < 0 || t.x >= COLS || t.y >= ROWS || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

