const SLOT_OF_LABEL = {
  "Right Hand": "rightHand",
  "Left Hand": "leftHand",
  Head: "head",
  Armor: "armor",
  Accessory: "accessory",
};

// Loot rolled from each felled enemy. "potion" tops up the shared supply.
// Keyed by ENEMY_KINDS id for the same reason as XP_ON_KILL.
// Three in ten for anyone who carries gear, one in ten for a hound that
// carries none, and a certainty for a boss's head. A seven-strong field pays
// one or two pieces -- enough to feel lucky, not enough to fund the company.
const LOOT_TABLES = {
  brigand: { chance: 0.3, pool: ["sword", "studded", "hide", "silkrobe", "circlet", "potion"] },
  rogue: { chance: 0.3, pool: ["huntbow", "leather", "hood", "boots", "elmbow", "charm", "potion"] },
  brute: { chance: 0.3, pool: ["greatsword", "studded", "ironhelm", "longsword", "spurs", "potion"] },
  thief: { chance: 0.3, pool: ["dagger", "leather", "hood", "boots", "potion"] },
  // A boss drops his head and nothing else: his kit is only ever earned by
  // turning the head in at the town Bounties board (BOUNTIES below).
  warlord: { chance: 1, pool: ["graskhead"] },
  knight: { chance: 0.3, pool: ["longsword", "towershield", "chain", "ironhelm", "potion"] },
  archerknight: { chance: 0.3, pool: ["elmbow", "hide", "boots", "huntbow", "potion"] },
  priest: { chance: 0.3, pool: ["staff", "robe", "charm", "circlet", "potion"] },
  elder: { chance: 0.3, pool: ["starstaff", "silkrobe", "circlet", "focusstone", "potion"] },
  attackdog: { chance: 0.1, pool: ["hide", "boots", "potion"] },
  paladin: { chance: 1, pool: ["aurelhead"] },
};
function rollDrop(unit, rolls) {
  const table = LOOT_TABLES[unit.kind];
  if (!table) return [];
  const out = [];
  for (let i = 0; i < Math.max(1, rolls || 1); i++)
    if (chance(table.chance)) out.push(pickOne(table.pool));
  return out;
}
// How many times a fall is searched, and by whose leave. A beast searches with
// its caller's hands, so a hound's kill counts for the hunter who set it on.
function lootRolls(feller, unitsArr) {
  if (!feller) return 1;
  const owner = feller.summon && feller.owner
    ? (unitsArr || []).find((u) => u.id === feller.owner.id) || feller.owner
    : feller;
  let rolls = 1;
  FLAG_KEYS.forEach((f) => {
    const inf = FLAG_INFO[f];
    if (inf.loots && hasFlag(owner, f)) rolls = Math.max(rolls, inf.loots);
  });
  return rolls;
}
// The town's bounty board. Keyed by boss kind: the head that proves the kill,
// the field whose reachability posts the notice, and the two rewards the head
// may be traded for -- one of the two, and the head is spent. The rewards are
// the boss's own kit, stripped from his loot pool above so the choice is real.
// Aurel swings the same cleaver Grask did, so his board offers it too: a
// second chance at the blade for whoever took the plate the first time.
// `posted` is the field that puts the notice up, not the field the boss stands
// on: the board wants a man wanted long before you reach him. The road is two
// chapters of five, and each chapter's boss is posted at its first field --
// Grask from the opening march, Aurel from the sixth.
const BOUNTIES = {
  warlord: { head: "graskhead", posted: "grassy", rewards: ["warplate", "warblade"] },
  paladin: { head: "aurelhead", posted: "fensteps", rewards: ["paladinplate", "aurelmace"] },
};
// A bounty is posted once its field can be marched to -- cleared or next on
// the road, the same rule the world map draws by -- and comes down when paid.
function postedBounties(cleared, claimed) {
  return Object.entries(BOUNTIES).filter(([kind, b]) =>
    !(claimed || []).includes(kind) &&
    (cleared.includes(b.posted) || b.posted === nextUnbeaten(cleared)));
}
let UID = 0;
function instantiate(itemKey) {
  const base = typeof itemKey === "string" ? ITEMS[itemKey] : itemKey;
  if (!base) return null;
  UID += 1;
  // The string id rides along, so anything holding the item can ask what it
  // is by id rather than by display name -- the bounty board needs to.
  return { ...base, key: typeof itemKey === "string" ? itemKey : base.key,
    uid: base.uid || `i${UID}_${Math.random().toString(36).slice(2, 7)}` };
}
function armourAllowed(cls) {
  const reg = PLAYER_CLASSES[cls];
  return reg && reg.armour ? reg.armour : ["heavy", "medium", "light", "robe"];
}
// Weapons are gated by class list, armour by weight. A Squire will not wear a
// robe; a Scholar cannot bear plate.
function canEquip(unit, item, slotKey) {
  if (!item) return true;
  if (item.classes && !item.classes.includes(unit.class)) return false;
  if (item.weight && !armourAllowed(unit.class).includes(item.weight)) return false;
  // Fearless (#13): armour is for the frightened. The heaviest is refused,
  // whatever the class would normally carry.
  if (item.weight === "heavy" && flagField(unit, "noHeavy")) return false;
  // A weapon in the off hand needs Dual Wield, and never a two-handed one.
  if (slotKey === "leftHand" && item.slot === "Right Hand")
    return hasFlag(unit, "dualwield") && !item.twoHanded;
  return true;
}
// Where an item may go. A weapon normally means the right hand; Dual Wield
// opens the left as well, which is the only reason this is a list.
function slotsFor(unit, item) {
  const primary = SLOT_OF_LABEL[item.slot];
  if (!primary) return [];
  // The primary slot is asked the same question as the off hand. Without it a
  // breastplate reported as wearable by a Scholar: the pack row lit up, and
  // the tap then did nothing at all.
  const out = canEquip(unit, item, primary) ? [primary] : [];
  if (primary === "rightHand" && canEquip(unit, item, "leftHand")) out.push("leftHand");
  return out;
}
// Every weapon a unit strikes with. One hand normally, two with Dual Wield.
function weaponsOf(u) {
  const e = u.equipment || {};
  return [e.rightHand, e.leftHand].filter((w) => w && w.slot === "Right Hand");
}
// Every stat an item may grant, named once. Both the row that lists what a
// thing does and the row that says what swapping it in would change read this
// list, because a field missing from one of them is a field the sheet silently
// refuses to mention: the Warded Silk Robe's Resistance and the Warlord's
// Plate's Health were both invisible in the pack beside the Defense they came
// with, and looked like items that granted nothing at all.
const ITEM_STAT_FIELDS = [
  { key: "atk", label: "ATK" },
  { key: "def", label: "DEF" },
  { key: "res", label: "RES" },
  { key: "hp", label: "HP" },
  { key: "mov", label: "MOV" },
  { key: "jump", label: "JMP" },
  { key: "dodge", label: "dodge", pct: true },
  { key: "block", label: "block", pct: true },
];
// How much of a stat an item carries, written the way a row shows it.
function itemStatAmount(f, n) {
  return f.pct ? `${Math.round(n * 100)}%` : `${n}`;
}
function itemStatBits(item) {
  const bits = ITEM_STAT_FIELDS
    .filter((f) => item[f.key])
    .map((f) => `+${itemStatAmount(f, item[f.key])} ${f.label}`);
  if (item.grants) bits.push(item.grants.name);
  return bits;
}

// Armour says what it is and lets the rules follow from that. Naming every
// class that could wear a thing is the same fact stated the long way round.
// Armour names its class wherever it is shown, because the class is what
// decides who may wear it. Cloth needs no suffix; the others read as armour.
const WEIGHT_LABEL = {
  heavy: "Heavy", medium: "Med", light: "Light", robe: "Cloth",
};

// What a thing is, in the short form every list shows beside its name: armour
// says its class, a weapon says how many hands it takes, a shield says it is
// one. Asked in one place, so a row never works it out for itself and the
// equipped sheet and the shop cannot disagree about it. Handedness used to be
// a stat bit, printed green at the end of the row beside the numbers; it is a
// kind, not a number, and now reads where the armour class does.
function itemKindLabel(it) {
  if (!it) return "";
  if (WEIGHT_LABEL[it.weight]) return WEIGHT_LABEL[it.weight];
  if (it.slot === "Left Hand") return "Shield";
  if (it.slot === "Right Hand") return it.twoHanded ? "2H" : "1H";
  return "";
}

// What swapping this in would actually change. The pack screen exists to answer
// one question — is this better than what they are wearing — and until now the
// player had to do the subtraction themselves.
function itemDelta(item, worn) {
  return ITEM_STAT_FIELDS.flatMap((f) => {
    const diff = (item[f.key] || 0) - ((worn && worn[f.key]) || 0);
    if (!diff) return [];
    return [{ up: diff > 0,
      text: `${diff > 0 ? "+" : "\u2212"}${itemStatAmount(f, Math.abs(diff))} ${f.label}` }];
  });
}

// What a won field yields from the bodies and the baggage. One number, read by
// the grant and by the checkpoint that records it, so the satchel on screen and
// the satchel on disk cannot disagree about what a victory was worth.
const POTIONS_PER_VICTORY = 1;
// What the company marches out with on day one.
const STARTING_SUPPLIES = { potion: 3 };
// The satchel is one count per CONSUMABLES key. It was a bare count of draughts
// once, so a save written then -- or a caller still passing one -- arrives as a
// number whose `.potion` is undefined, silently emptying the satchel. Normalised
// at the one door supplies enter by, rather than at each call.
function suppliesOf(sup) {
  if (typeof sup === "number") return { potion: sup };
  return sup || { potion: 0 };
}
const POTION_INFO = {
  name: "Healing Draught",
  detail: `A bitter herbal tonic that knits wounds closed. Restores a quarter of the drinker's health to the user or an adjacent ally. A fighter may take one thing from the satchel each turn, and only before they strike \u2014 never after. The party shares a single supply, and scavenges one more after every victory.`,
};
// --- Field consumables ---------------------------------------------------
// One row per thing the company carries into battle. `heal` mends, `cures`
// strips statuses, `raise` calls back the fallen; `shelf` is the chance the
// apothecary has any in on a given visit and `stock` how many they put out.
// Everything downstream -- the shop shelf, the field menu, the loot table, the
// save -- reads this table, so another item is a row here and nothing else.
const CONSUMABLES = {
  potion: {
    name: POTION_INFO.name, short: "Draught", sub: "Restores a quarter of their health", icon: "FlaskConical",
    price: 30, shelf: 1, stock: 3, reach: 1, healShare: POTION_HEAL_SHARE, detail: POTION_INFO.detail,
  },
  antidote: {
    name: "Antidote", short: "Antidote", sub: "Cures Poison", icon: "Leaf",
    price: 60, shelf: 0.22, stock: 1, reach: 1, cures: ["poison"],
    detail: "A chalky white draught that drives the venom out. Cures Poison on the user or an adjacent ally. The apothecary seldom has one in.",
  },
  icecream: {
    name: "Ice Cream", short: "Ice Cream", sub: "Puts out Burning", icon: "Snowflake",
    price: 60, shelf: 0.22, stock: 1, reach: 1, cures: ["burn", "firevuln"],
    detail: "Kept in the cellar under straw and snow, and worth every coin of it. Puts out Burning \u2014 and the tinder-dryness that invites it \u2014 on the user or an adjacent ally.",
  },
  soup: {
    name: "Soup", short: "Soup", sub: "Thaws Frozen, Frostbitten and Slowed", icon: "Flame",
    price: 60, shelf: 0.22, stock: 1, reach: 1, cures: ["freeze", "frostbite", "slow"],
    detail: "Thick, scalding, and mostly barley. Thaws a Frozen or Frostbitten ally and drives out the deep cold that Slows them.",
  },
  phoenix: {
    name: "Phoenix Down", short: "Phoenix", sub: "Raises one fallen ally", icon: "Feather",
    price: 320, shelf: 0.08, stock: 1, reach: 2, raise: 0.5,
    detail: "A single ember-coloured feather, and the rarest thing on the apothecary's shelf. Calls a fallen companion back onto a tile beside the bearer at half their health, keeping every scrap of experience they had earned. Nobody is called back twice in one battle.",
  },
};
const CONSUMABLE_KEYS = Object.keys(CONSUMABLES);

