// Which texture set a tile draws from: the first zone covering it, or the
// board's own. Asked by the ground and by the faces alike, so a zone cannot
// grass a floor and leave a stone wall standing under it.
function texAt(x, y) {
  for (const z of ACTIVE_TEX_ZONES)
    if (x >= z.x0 && x <= z.x1 && y >= z.y0 && y <= z.y1) return z.tex;
  return ACTIVE_TEX;
}
function pickTex(list, x, y) {
  return list[Math.floor(tileHash(x, y, 4) * list.length) % list.length];
}
// Highlights are dithered checkerboards rather than flat alpha, like era hardware.
const OVERLAY_TINT = {
  attack: "rgba(214,42,52,0.86)",
  move: "rgba(0,132,205,0.86)",
  ability: "rgba(128,68,178,0.86)",
  heal: "rgba(62,168,88,0.84)",
  deploy: "rgba(28,190,214,0.78)",
  selected: "rgba(254,231,97,0.80)",
  pass: "rgba(0,132,205,0.42)",
  path: "rgba(120,200,255,0.95)",
};

function terrainStyle(h, override, feature, x, y) {
  // Which texture a feature wears is declared in FEATURE_INFO, and a hazard
  // that covers the ground says so in HAZARD_INFO. Neither means a second list
  // of names kept in step with the first.
  const laid = hazardRule(hazardAt(x, y));
  const ground = (laid && laid.ground && laid.tex) ||
    (feature && FEATURE_INFO[feature] && FEATURE_INFO[feature].tex);
  let tex;
  if (ground) tex = pickTex(TEX[ground], x, y);
  else if (h >= CRAG_HEIGHT) tex = pickTex(TEX[texAt(x, y).raised || "spire"], x, y);
  else if (h >= 1) tex = pickTex(TEX[texAt(x, y).raised || "dirt"], x, y);
  else tex = pickTex(TEX[texAt(x, y).ground || "grass"], x, y);

  const layers = [];
  const sizes = [];
  if (override && OVERLAY_TINT[override]) {
    // flat wash so highlighted tiles read as solid colour, not dithered
    layers.push(`linear-gradient(${OVERLAY_TINT[override]}, ${OVERLAY_TINT[override]})`);
    sizes.push("100% 100%");
  }
  layers.push(`url(${tex})`);
  sizes.push(`${TILE}px ${TILE}px`);
  return {
    backgroundImage: layers.join(","),
    backgroundSize: sizes.join(","),
    imageRendering: "pixelated",
    boxShadow: BEVEL,
  };
}

function wallStyle(x, y) {
  // The face of raised ground is its own texture, chosen per map: earth cliff
  // for open country, cut stone for a standing fortress, ruined courses for a
  // fallen one. A raised tile carrying water is a pool, and its faces fall.
  const f = getFeature(x, y);
  const fam = (f === "water" || f === "deepwater") ? "waterfall"
    : (texAt(x, y).riser || "wall");
  return {
    backgroundImage: `url(${pickTex(TEX[fam] || TEX.wall, x, y)})`,
    backgroundSize: `${TILE}px ${TILE}px`,
    imageRendering: "pixelated",
    boxShadow: "inset 0 1px 0 rgba(255,255,255,0.12), inset 0 -6px 8px rgba(0,0,0,0.45)",
  };
}

function getWalls() {
  const walls = [];
  const dirs = [
    { dx: 0, dy: 1, edge: "S" },
    { dx: 0, dy: -1, edge: "N" },
    { dx: 1, dy: 0, edge: "E" },
    { dx: -1, dy: 0, edge: "W" },
  ];
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      const h = getHeight(x, y);
      if (h <= 0) continue;
      const myZ = visualHeight(h) * HEIGHT_STEP;
      dirs.forEach(({ dx, dy, edge }) => {
        const nx = x + dx, ny = y + dy;
        const inBounds = nx >= 0 && ny >= 0 && nx < COLS && ny < ROWS;
        const neighborH = inBounds ? getHeight(nx, ny) : 0;
        const neighborZ = visualHeight(neighborH) * HEIGHT_STEP;
        if (myZ > neighborZ) {
          walls.push({ id: `${edge}-${x}-${y}`, x, y, edge, heightPx: myZ - neighborZ, neighborZ: neighborZ });
        }
      });
    }
  }
  return walls;
}

