// Cheap deterministic hash, so the tavern's offer is stable within a visit but
// changes once you have cleared another battle.
function strHash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) / 4294967295;
}

