const COUNTER_ODDS = { front: 1, side: 0.5, behind: 0 };
function counterChance(defender, attacker) {
  if (statusFlag(defender, "noDefense")) return 0;
  if (manhattan(attacker, defender) > effRange(defender)) return 0;
  return COUNTER_ODDS[attackAngle(defender, attacker)];
}
// A bow is useless with a swordsman inside its reach: a fighter who fights at
// range answers a *melee* attacker with a fist. One blow, Strength only,
// whoever they are. Another ranged fighter is a different matter -- if a rogue
// can shoot from beside them, they can shoot back, so the bow answers the bow
// however close it was loosed. A melee attacker is adjacent by definition, so
// the two reaches are the whole question.
const BARE_HANDS = { bare: true, hits: 1 };
function counterBare(defender, attacker) {
  return effRange(defender) >= 2 && effRange(attacker) <= 1;
}
// Whether an answer is possible at all -- what the forecast asks.
function canCounter(defender, attacker) {
  return counterChance(defender, attacker) > 0;
}
// Whether one actually comes -- what the blow itself asks, once.
function rollsCounter(defender, attacker) {
  return chance(counterChance(defender, attacker));
}
// `ability` is what makes the numbers honest for a skill: its power, its extra
// blows, and whether it is a bane to whatever it is aimed at.
function getForecast(attacker, defender, ability) {
  const { angle, block, dodge, staggered, coverDodge: cd } = evadeChances(attacker, defender);
  const { heightBonus, cover, bane } = computeDamage(attacker, defender, undefined, ability);
  // Every blow this attack consists of, so a Dual Wielder's forecast is honest.
  const blows = blowsOf(attacker, ability);
  // A skill that carries no damage of its own -- Freeze, the firepot -- lands
  // as nothing here too. `strikeOutcome` and `sureOutcome` already honour it;
  // the forecast did not, so the confirm panel promised a kill the blow could
  // never make.
  const dmg = ability && ability.noDamage ? 0 : blows.reduce(
    (t, w) => t + Math.round(computeDamage(attacker, defender, w, ability).dmg * ((ability && ability.power) || 1)),
    0
  );
  // Nothing lands on a consecrated defender, and the panel says so rather
  // than promising a number the blow will not deliver.
  const warded = statusFlag(defender, "invincible");
  const lethal = !warded && dmg > 0 && dmg >= defender.hp;
  let counter = null;
  if (canCounter(defender, attacker)) {
    const bare = counterBare(defender, attacker);
    const c = computeDamage(defender, attacker, undefined, bare ? BARE_HANDS : undefined);
    counter = { damage: c.dmg, lethal: c.dmg >= attacker.hp, bare,
      chance: counterChance(defender, attacker) };
  }
  return {
    damage: warded ? 0 : dmg, warded, blows: blows.length, bane, critPct: Math.round(critChanceOf(attacker) * 100),
    heightBonus, cover, coverDodgePct: Math.round(cd * 100),
    // A sure blow cannot be blocked or dodged, so the chance of evading it is
    // nought. Answered here rather than by whoever draws it, so the panel can
    // show one number instead of branching into a sentence.
    angle, evadePct: ability && ability.sure ? 0 : Math.round((block + dodge) * 100),
    lethal, counter, staggered,
  };
}

// One bash, resolved (M1): the sure blow, the shove, the fall and the black
// water, identical whoever swings it. Pure outcome only -- the theatre stays
// with whichever phase is acting. The player's branch and the enemy executor
// both read this, so there is exactly one answer to what a shove does.
function bashOutcome(attacker, target, units, ab) {
  const push = bashPushPreview(attacker, target, units, (ab && ab.shove) || 1);
  const dmg = Math.max(1, attackPower(attacker, ab) - computeDef(target) - coverDef(target.x, target.y));
  const { hpAfter: hpAfterHit, lethal: diesFromHit } = damageOutcome(target, dmg);
  const willPush = !diesFromHit && push.canPush;
  const drowned = willPush && push.drowns;
  const fallDmg = willPush ? push.fallDmg : 0;
  const hpFinal = drowned ? 0 : Math.max(0, hpAfterHit - fallDmg);
  return { push, dmg, willPush, drowned, fallDmg, hpFinal, dies: hpFinal <= 0 };
}
// How far a shove carries, and what it runs into. A Shield Bash moves someone
// one tile; a Throw carries them three. It is the same walk either way, taken
// a step at a time, so distance is a number on the skill rather than a second
// function that would drift from this one.
function bashPushPreview(unit, target, units, dist = 1) {
  // A planted target goes nowhere, so nothing after this matters. Asked as a
  // field, so whichever passive grants it, this line never changes.
  if (flagField(target, "noShove"))
    return { canPush: false, px: target.x, py: target.y, drop: 0, fallDmg: 0, steps: 0,
      drowns: false, uphill: false, blocked: false, offBoard: false, rooted: true, hitId: null };
  const dir = directionTo(unit, target);
  const v = DIR_VEC[dir];
  const th = getHeight(target.x, target.y);
  let px = target.x, py = target.y, steps = 0;
  let drowns = false, uphill = false, blocked = false, offBoard = false, hitId = null;
  for (let i = 0; i < dist; i++) {
    const nx = px + v.dx, ny = py + v.dy;
    if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) { offBoard = true; break; }
    const met = units.find((o) => o.alive && o.id !== target.id && o.x === nx && o.y === ny);
    // Someone in the way stops the flight and wears the landing.
    if (met) { blocked = true; hitId = met.id; break; }
    if (getHeight(nx, ny) > getHeight(px, py)) { uphill = true; break; }
    px = nx; py = ny; steps++;
    if (isDrowning(px, py)) { drowns = true; break; }
  }
  const canPush = steps > 0;
  const drop = canPush && !drowns ? th - getHeight(px, py) : 0;
  const fallDmg = drop >= 2 ? drop * 2 : 0;
  return { canPush, px, py, steps, drop, fallDmg, drowns, uphill, blocked, offBoard, hitId };
}

// Experience is won by the company, not the individual: every kill feeds a
// shared pool, split at the end of the battle among the fighters still
// standing. The fallen take no share.
// The ladder (BALANCE-PLAN): 50/100/150 through level 3, +25 for the step to
// 5, then +5 a level -- a steep opening and a near-linear tail, so level 20
// arrives around the fiftieth battle rather than the hundredth.
function xpForNextLevel(u) {
  const L = u.level || 1;
  return L <= 3 ? L * XP_PER_LEVEL : 175 + 5 * (L - 4);
}
function canLevel(u) {
  return (u.xp || 0) >= xpForNextLevel(u);
}
// How many ways the company's winnings split (B2): by the five the company is
// meant to be until it truly is five, and one fewer for every fighter
// deliberately benched -- never fewer ways than were actually fielded.
function xpDivisor(marchedCount, benchedCount) {
  return Math.max(marchedCount, PARTY_MAX - benchedCount);
}
// The settlement itself: the living take their share, the fallen forfeit what
// they held, and a summoned beast was never on the books at all.
function settleShares(u, share) {
  if (u.team !== "player" || u.summon) return u;
  // What they held before the reckoning, kept on the fighter so the tally can
  // report a loss as well as a gain. It used to work the opening figure out by
  // subtracting the share from the closing one, which is only right for the
  // living: a fallen fighter forfeits the lot, and no arithmetic on nothing
  // recovers what the nothing replaced.
  const was = u.xp || 0;
  return u.alive
    ? { ...u, xp: was + share, xpWas: was }
    : { ...u, xp: 0, xpWas: was };
}

const STEP_DIRS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
// What one step costs this unit, or null if it is no step at all. The walk and
// the AI's flow field both ask this, so "where can I go" and "how far is that
// really" can never disagree about a lake, a cliff or a wall of ice.
function stepCost(unit, from, to, blocked) {
  if (!standable(to.x, to.y) && !(isDeepWater(to.x, to.y) && hasFlag(unit, "coldfeet"))) return null;
  if (blocked && blocked.has(key(to.x, to.y))) return null;
  if (Math.abs(getHeight(to.x, to.y) - getHeight(from.x, from.y)) > effJump(unit)) return null;
  return moveCost(to.x, to.y, unit);
}

// Cost-aware pathing: thickets and rubble cost 2 movement, so reach is no
// longer a plain radius. Uses repeated relaxation since costs are tiny.
function getReachableTiles(unit, units, keepOccupied) {
  const impassable = new Set();
  const allyOccupied = new Set();
  units.forEach((u) => {
    if (!u.alive || u.id === unit.id) return;
    if (u.team === unit.team) allyOccupied.add(key(u.x, u.y));
    else impassable.add(key(u.x, u.y));
  });

  const budget = statusFlag(unit, "noMove") ? 0 : unit.secondWind || effMov(unit);
  const best = new Map([[key(unit.x, unit.y), 0]]);
  // Where each tile was first reached from. The walk already knows; keeping it
  // is what lets the board draw the route rather than guess at it.
  const from = new Map();
  const queue = [{ x: unit.x, y: unit.y, c: 0 }];
  while (queue.length) {
    const cur = queue.shift();
    if (cur.c > (best.get(key(cur.x, cur.y)) ?? Infinity)) continue;
    for (const [dx, dy] of STEP_DIRS) {
      const to = { x: cur.x + dx, y: cur.y + dy };
      const step = stepCost(unit, cur, to, impassable);
      if (step === null) continue;
      const k = key(to.x, to.y);
      const nc = cur.c + step;
      if (nc > budget) continue;
      if (nc >= (best.get(k) ?? Infinity)) continue;
      best.set(k, nc);
      from.set(k, key(cur.x, cur.y));
      queue.push({ ...to, c: nc });
    }
  }
  // Shepherd and To the Rescue reach past the walk entirely: any free tile
  // beside an ally in real trouble is a destination, whatever the distance.
  // "Real trouble" is the flag's own threshold (`reachAlly`), so the two
  // passives differ only in data. Folded in here so every consumer of reach
  // — highlights, the tap handler, the AI — agrees.
  const rescueAt = FLAG_KEYS.reduce(
    (t, f) => (FLAG_INFO[f].reachAlly && hasFlag(unit, f) ? Math.max(t, FLAG_INFO[f].reachAlly) : t), 0);
  if (rescueAt > 0) {
    units.forEach((a) => {
      if (!a.alive || a.team !== unit.team || a.id === unit.id) return;
      // Strictly below the threshold, not at it: "less than 30%" is what the
      // passives promise, and an ally sitting exactly on the line is not yet
      // in the trouble the words describe.
      if (a.hp >= maxHpOf(a) * rescueAt) return;
      [[1, 0], [-1, 0], [0, 1], [0, -1]].forEach(([dx, dy]) => {
        const nx = a.x + dx, ny = a.y + dy;
        const k = key(nx, ny);
        if (!standable(nx, ny) || impassable.has(k) || best.has(k)) return;
        best.set(k, budget);
      });
    });
  }
  const tiles = Array.from(best.keys())
    .filter((k) => keepOccupied || !allyOccupied.has(k))
    .map((k) => {
      const [x, y] = k.split(",").map(Number);
      return { x, y };
    });
  // The route to one of those tiles, walked backwards through the search. A
  // Shepherd's step has no route, so it reports just the destination.
  tiles.pathTo = (x, y) => {
    const start = key(unit.x, unit.y);
    let at = key(x, y);
    if (!best.has(at)) return [];
    const out = [];
    while (at && at !== start) {
      const [px, py] = at.split(",").map(Number);
      out.unshift({ x: px, y: py });
      at = from.get(at);
      if (out.length > COLS * ROWS) break;
    }
    return out;
  };
  return tiles;
}

// How far every tile on the board really is from `seed`, for this unit, with
// no movement budget at all: the same relaxation the walk uses, run outward
// until the board is exhausted. Straight-line distance is what left an enemy
// pacing the shore of a lake -- the tile nearest its mark as the crow flies is
// a dead end, and a planner that can only see one turn of movement never finds
// that out. The seed's own tile is passable even when someone is standing on
// it, since the seed is usually the fighter being hunted.
function travelField(unit, units, seed) {
  const seedKey = key(seed.x, seed.y);
  const blocked = new Set();
  units.forEach((u) => {
    if (!u.alive || u.id === unit.id || u.team === unit.team) return;
    if (key(u.x, u.y) !== seedKey) blocked.add(key(u.x, u.y));
  });
  const best = new Map([[seedKey, 0]]);
  const queue = [{ x: seed.x, y: seed.y, c: 0 }];
  while (queue.length) {
    const cur = queue.shift();
    if (cur.c > (best.get(key(cur.x, cur.y)) ?? Infinity)) continue;
    for (const [dx, dy] of STEP_DIRS) {
      const to = { x: cur.x + dx, y: cur.y + dy };
      const step = stepCost(unit, cur, to, blocked);
      if (step === null) continue;
      const k = key(to.x, to.y);
      const nc = cur.c + step;
      if (nc >= (best.get(k) ?? Infinity)) continue;
      best.set(k, nc);
      queue.push({ ...to, c: nc });
    }
  }
  const costAt = (x, y) => best.get(key(x, y)) ?? Infinity;
  return {
    costAt,
    // Standing on someone is not an option, so the cost of getting to a unit
    // is the cost of reaching the ground beside them.
    costNear: (u) =>
      Math.min(costAt(u.x, u.y), ...STEP_DIRS.map(([dx, dy]) => costAt(u.x + dx, u.y + dy))),
  };
}

// How badly this attacker could hurt that defender, judged the way a fighter
// judges it: the share of their health one blow takes, counting the armour,
// the cover and the height that are already in the blow, and any venom it
// leaves behind. A frail caster who dies in two is worth more attention than a
// scout who dies in three, and this is what says so -- the old measure summed
// health and armour into one number, which flattened exactly that difference.
function bitePerBlow(attacker, defender) {
  const { dmg } = computeDamage(attacker, defender);
  const venom = attacker.venom ? Math.max(1, attackPower(attacker) * DOT_SHARE) : 0;
  return (dmg + venom) / Math.max(1, defender.hp);
}
// How many blows of it they have left in them, venom aside: a mark the next
// blow but one would finish is a mark worth turning to now.
function blowsToKill(attacker, defender) {
  const { dmg } = computeDamage(attacker, defender);
  return Math.ceil(defender.hp / Math.max(1, dmg));
}

// Weighted pick: heavier entries come up more often, but nothing is certain.
function weightedPick(entries) {
  const total = entries.reduce((t, e) => t + e.w, 0);
  if (total <= 0) return entries[0] && entries[0].v;
  let r = rng() * total;
  for (const e of entries) {
    r -= e.w;
    if (r <= 0) return e.v;
  }
  return entries[entries.length - 1].v;
}

// What the other side could do next turn, tile by tile (#AI-B). For every
// living enemy of the mover: everywhere they could walk, and everything within
// reach of those tiles -- folded into one map of expected damage and one of
// how many of them can arrive. Built off the same walk and the same damage
// function the player's own turn uses, so it can never dread something the
// player could not actually do. Only called when AI_TACTICS is on.
function threatMap(unit, units) {
  const dmg = new Map();
  const arrivals = new Map();
  units.forEach((p) => {
    if (!p.alive || p.team === unit.team) return;
    const blow = computeDamage(p, unit).dmg;
    const reach = effRange(p);
    const seen = new Set();
    getReachableTiles(p, units, true).forEach((from) => {
      for (let dx = -reach; dx <= reach; dx++) {
        const room = reach - Math.abs(dx);
        for (let dy = -room; dy <= room; dy++) {
          const k = key(from.x + dx, from.y + dy);
          if (seen.has(k)) continue;
          seen.add(k);
          dmg.set(k, (dmg.get(k) || 0) + blow);
          arrivals.set(k, (arrivals.get(k) || 0) + 1);
        }
      }
    });
  });
  return {
    damageAt: (x, y) => dmg.get(key(x, y)) || 0,
    attackersAt: (x, y) => arrivals.get(key(x, y)) || 0,
  };
}
// How much this fighter minds any of that, and what sort of fighter it is:
// properties of the kind, read from the same table that gives them their
// sprite and their loot.
function cautionOf(u) {
  const kind = ENEMY_KINDS[u.kind];
  return kind && kind.ai && kind.ai.caution !== undefined ? kind.ai.caution : DEFAULT_CAUTION;
}
function roleOf(u) {
  const kind = ENEMY_KINDS[u.kind];
  return (kind && kind.ai && kind.ai.role) || DEFAULT_ROLE;
}
// Who moves first (#AI-C): the ones who hold the line, then the ones who work
// the flanks, then the ones who fight from behind both. Ties keep the order
// they were given in. With the flag off the roster order stands.
const ROLE_ORDER = { bruiser: 0, skirmisher: 1, support: 2 };
function activationOrder(list) {
  if (!AI_TACTICS) return list.map((u) => u.id);
  return list
    .map((u, i) => ({ u, i }))
    .sort((a, b) =>
      ((ROLE_ORDER[roleOf(a.u)] ?? 1) - (ROLE_ORDER[roleOf(b.u)] ?? 1)) || (a.i - b.i))
    .map((e) => e.u.id);
}
// What the side has committed to this phase: damage booked, by target.
// Threaded through the activation loop exactly as the board is, and read only
// when the flag is on. Pure, so a plan that never happens marks nothing.
function markTarget(ledger, targetId, dmg) {
  if (!targetId) return ledger || {};
  const out = { ...(ledger || {}) };
  out[targetId] = (out[targetId] || 0) + (dmg || 0);
  return out;
}

// Enemy AI. Deliberately not deterministic: targets are drawn from a weighted
// pool and tile scores carry jitter, so the same opening plays differently.
// Enemies favour finishing wounded fighters, flanking, high ground and cover.
function planEnemyAction(units, unitId, ledger) {
  const unit = units.find((u) => u.id === unitId);
  const players = units.filter((u) => u.team === "player" && u.alive);
  if (!unit || !unit.alive || players.length === 0) return null;

  const reachable = getReachableTiles(unit, units);
  const routeTo = (x, y) => (reachable.pathTo ? reachable.pathTo(x, y) : []);
  // A broken nerve runs (#15): a fleeing unit spends its whole phase getting
  // away -- the tile in reach that leaves the most ground between them and
  // the nearest player -- and attacks nobody at all.
  if (statusFlag(unit, "flee")) {
    const spot = reachable.reduce((b, t) => {
      const d = Math.min(...players.map((p) => manhattan(t, p)));
      return !b || d > b.d ? { t, d } : b;
    }, null);
    const dest = spot ? spot.t : { x: unit.x, y: unit.y };
    return { x: dest.x, y: dest.y, facing: unit.facing, targetId: null, skillId: null,
      route: routeTo(dest.x, dest.y), cleave: null };
  }
  // What a tile costs in blood, as against what it offers in ground (#AI-B).
  // Danger is a discount and never a veto: a killing blow ignores it outright,
  // and a brute barely notices it in the first place. All of it collapses to
  // zero with the flag off, and the threat map is not even built.
  const threat = AI_TACTICS ? threatMap(unit, units) : null;
  const caution = AI_TACTICS ? cautionOf(unit) : 0;
  const crowd = (t) =>
    Math.max(0, units.filter((a) => a.alive && a.team === unit.team && a.id !== unit.id
      && manhattan(t, a) === 1).length - 1) * CLUMP_PENALTY;
  const screens = () => units.filter((a) =>
    a.alive && a.team === unit.team && a.id !== unit.id && roleOf(a) === "bruiser");
  const shelter = (t) => {
    if (roleOf(unit) !== "support") return 0;
    const line = screens();
    return line.length ? Math.min(...line.map((a) => manhattan(t, a))) * SHELTER_PULL : 0;
  };
  const risk = (t, lethal) =>
    !threat || lethal
      ? 0
      : (threat.damageAt(t.x, t.y) + threat.attackersAt(t.x, t.y) * PILE_ON) * caution * DANGER_WEIGHT
        + crowd(t) + shelter(t);

  // The Order tends its own (M2): a unit carrying a mend, off cooldown, with
  // a wounded ally reachable from somewhere it can stand, heals instead of
  // hitting. Worst-off ally first, nearest qualifying tile. This is the
  // planner's one ally-facing branch, and any future support skill rides it.
  const mend = getSkills(unit).find(
    (sk) => sk.type === "mend" && cooldownOf(unit, sk.id) === 0);
  if (mend) {
    const hurt = units
      .filter((v) => v.alive && v.team === unit.team && v.id !== unit.id && v.hp / maxHpOf(v) < 0.7)
      .sort((a, b) => a.hp / maxHpOf(a) - b.hp / maxHpOf(b));
    for (const ally of hurt) {
      const spots = reachable.filter((t) => canTarget(t, ally, abilityRange(unit, mend)));
      if (!spots.length) continue;
      const spotScore = (t) => manhattan(t, unit) * 0.5 + risk(t, false);
      const dest = spots.reduce((b, t) => (!b || spotScore(t) < spotScore(b) ? t : b), null);
      return { x: dest.x, y: dest.y, facing: directionTo(dest, ally),
        targetId: ally.id, skillId: mend.id, route: routeTo(dest.x, dest.y), cleave: null };
    }
  }
  const canHit = (p) => reachable.some((t) => canTarget(t, p, effRange(unit)));
  const hittable = players.filter(canHit);
  const pool = hittable.length > 0 ? hittable : players;
  // One walk outward from where it stands, so the planner knows which of the
  // enemy it can actually get to before it decides who to want. Only worth
  // asking when nothing is already in reach.
  const home = hittable.length > 0 ? null : travelField(unit, units, unit);

  // What a shove would actually do, which the planner has never asked. The
  // maths already exists -- bashOutcome knows about the water at the bottom of
  // the push and the fall at the end of it -- so this is one question, not a
  // new rule. Asked only of the kinds that carry a shove.
  const shove = getSkills(unit).find((sk) => sk.type === "bash" && cooldownOf(unit, sk.id) === 0);
  const shoveFrom = (t, p) =>
    !!shove && canTarget(t, p, shove.range)
      ? bashOutcome({ ...unit, x: t.x, y: t.y }, p, units, shove)
      : null;
  // The ground finishing them, rather than the blow: drowned, or dropped far
  // enough to matter. That is the part nothing else in the planner can see.
  const shoveKills = (t, p) => {
    const out = shoveFrom(t, p);
    return !!out && out.dies && (out.drowned || out.fallDmg > 0);
  };
  // A boss does not shop for a soft target. Cover, backline hunting and the
  // rest are how a fighter who can be killed picks a mark; a warlord walks at
  // whoever is nearest and swings. Weighted, not forced, so he is still not a
  // script -- but the nearest of the company is what he wants.
  const fearless = !!(ENEMY_KINDS[unit.kind] || {}).boss;
  const target = weightedPick(
    pool.map((p) => {
      if (fearless) return { v: p, w: 100 / (1 + manhattan(unit, p)) };
      let w = 10 * bitePerBlow(unit, p);            // whose health this blow eats
      const { dmg } = computeDamage(unit, p);
      if (dmg >= p.hp) w *= 5;                       // finish the wounded
      else if (blowsToKill(unit, p) <= 2) w *= 2;    // and the next but one
      else if (p.hp <= maxHpOf(p) * 0.4) w *= 2.2;      // press the hurt
      if (effRange(p) >= 2) w *= 1.4;                // hunt the backline
      if (statusFlag(p, "noDefense")) w *= 1.8;      // pile onto the helpless
      if (coverDef(p.x, p.y) > 0 || coverDodge(p.x, p.y) > 0) w *= 0.7;
      // Across the lake, over the cliff, behind the ice: the crow's line said
      // close, the road says never. Weighted almost out rather than forbidden,
      // so a company that has walled itself in is still hunted rather than
      // ignored -- and never applied to someone already in reach, since an
      // archer can shoot across water it cannot walk.
      if (home && !Number.isFinite(home.costNear(p))) w *= 0.02;
      // The side fights as a side (#AI-C): whoever is already marked this
      // phase draws the rest in -- until enough is booked to finish them, at
      // which point another blow is one thrown at a corpse.
      const booked = (AI_TACTICS && ledger && ledger[p.id]) || 0;
      if (booked > 0) w *= booked >= p.hp ? OVERKILL_DISCOUNT : FOCUS_BONUS;
      // Someone standing with their back to the water is a different
      // proposition entirely, whatever their health says.
      if (reachable.some((t) => shoveKills(t, p))) w *= SHOVE_WEIGHT;
      return { v: p, w: Math.max(0.05, w) };
    })
  );

  const isRanged = effRange(unit) >= 2;
  // Ground a unit can plainly see is dangerous: fire it would stand in, gas it
  // would breathe. Traps are deliberately absent from this — hidden is the
  // whole point of a trap, and `hazardTick` never reports one.
  const dread = (t) => {
    const effect = hazardTick(t.x, t.y);
    if (!effect) return 0;
    return HAZARD_DREAD + effect.dmg * 2;
  };
  const quakeReady = getSkills(unit).some((sk) => sk.id === "quake") && cooldownOf(unit, "quake") === 0;
  let dest = { x: unit.x, y: unit.y };
  let targetId = null;

  if (hittable.includes(target)) {
    const options = reachable.filter((t) => canTarget(t, target, effRange(unit)));
    const angleScore = { behind: 0, side: 1, front: 2 };
    const scoreOf = (t) => {
      const dist = manhattan(t, target);
      // Which side of them you stand on decides where the push goes, so a tile
      // that lines the water up is worth more than a better angle on the same
      // fighter.
      const shoving = shoveKills(t, target);
      const from = { ...unit, x: t.x, y: t.y };
      // A blow that finishes them is worth walking into anything for.
      const lethal = shoving || computeDamage(from, target).dmg >= target.hp;
      let sc = angleScore[attackAngle(target, t)] * 4 - getHeight(t.x, t.y) * 2;
      sc -= coverDef(t.x, t.y) * 1.2 + coverDodge(t.x, t.y) * 10;   // stand in cover
      sc += isRanged ? -dist * 2.5 : dist * 0.1;
      if (quakeReady) sc -= players.filter((p) => manhattan(t, p) <= QUAKE_REACH).length * 6;
      if (shoving) sc -= SHOVE_KILL_BONUS;                          // into the water with them
      sc += dread(t);                                               // not into the fire
      sc += risk(t, lethal);                                        // and not into the spears
      // The blow that comes straight back.
      if (AI_TACTICS && !lethal)
        sc += computeDamage(target, from, undefined,
          counterBare(target, from) ? BARE_HANDS : undefined).dmg
          * counterChance(target, from) * caution * COUNTER_WEIGHT;
      return sc + rng() * 2.6;                                      // jitter breaks ties
    };
    dest = options.reduce((best, t) => (scoreOf(t) < scoreOf(best) ? t : best), options[0]);
    targetId = target.id;
  } else if (reachable.length > 0) {
    // Closing the gap by the road rather than the crow's line: the field is
    // the real remaining travel cost from a tile, so a lake gets walked around
    // instead of paced along. Cover and height still shape the way in, and the
    // jitter still means it is not always the single best tile.
    const field = travelField(unit, units, target);
    const ground = (t) =>
      -coverDef(t.x, t.y) -
      coverDodge(t.x, t.y) * 8 -
      getHeight(t.x, t.y) * 0.8 +
      dread(t) +
      risk(t, false) +
      rng() * 2.2;
    // Nothing in reach leads anywhere: no amount of walking helps this turn,
    // so take the strongest ground available instead of pressing up against
    // the water for the rest of the battle.
    const stuck = reachable.every((t) => !Number.isFinite(field.costAt(t.x, t.y)));
    // A boss never picks its ground. Cover and a high place are for fighters
    // who can be killed; a warlord circling the company to find a thicket
    // reads as fear, and the ground terms were enough to buy one two tiles of
    // distance. They still keep out of a fire, which is sense rather than
    // nerve, and they still jitter a little so an opening is not a script.
    const fearless = !!(ENEMY_KINDS[unit.kind] || {}).boss;
    const approach = (t) => (stuck ? 0 : field.costAt(t.x, t.y) * 2)
      + (fearless ? dread(t) + rng() * 0.8 : ground(t));
    dest = reachable.reduce((best, t) => (approach(t) < approach(best) ? t : best), reachable[0]);
  }

  const facing = directionTo(dest, target);
  const quakeVictims = quakeReady ? quakeVictimsFrom(dest, players) : null;

  // One ready skill is considered against the plain swing it would replace.
  // Worth is expected damage plus a flat premium for leaving something behind,
  // so control skills get used even when they hit softer.
  let skillId = null;
  // What this plan books against its mark, so the fighters after it know how
  // much of the target is already spoken for. Costs nothing to report with the
  // flag off; the pool simply does not read it.
  let expected = 0;
  if (targetId) {
    const from = { ...unit, x: dest.x, y: dest.y };
    // What a blow takes off them, in health. A shove counts the fall or the
    // water at the end of it, which is the whole of the difference between a
    // Knight in a field and a Knight beside a river.
    const damageOf = (sk) => {
      if (sk && sk.type === "bash") {
        const out = bashOutcome(from, target, units, sk);
        return Math.min(target.hp, target.hp - out.hpFinal);
      }
      return computeDamage(from, target, undefined, sk).dmg * ((sk && sk.power) || 1);
    };
    const plain = damageOf(undefined);
    const ready = getSkills(unit).filter(
      (sk) => (sk.type === "strike" || sk.type === "bash")
        && cooldownOf(unit, sk.id) === 0 && canTarget(from, target, sk.range)
    );
    const best = ready.reduce((b, sk) => {
      const worth = damageOf(sk) +
        (sk.inflict ? SKILL_CONTROL_WORTH : 0) + (sk.sure ? SKILL_SURE_WORTH : 0);
      return !b || worth > b.worth ? { sk, worth } : b;
    }, null);
    if (best && best.worth > plain) skillId = best.sk.id;
    expected = skillId ? damageOf(best.sk) : plain;
  }
  return { x: dest.x, y: dest.y, facing, targetId, skillId, expected,
    route: routeTo(dest.x, dest.y),
    cleave: quakeVictims };
}

// A frozen unit is marked done for the phase before it can act.
// Anything that makes a unit lose its turn works the same way, whether it is
