    // certainty (`chance`), and never lands on a unit whose passive shrugs
    // off the ground itself (Sure-Footed's `terrainImmune`).
    const spared = (effect.foes && effect.team === u.team)
      || (effect.chance !== undefined && !chance(effect.chance))
      || flagField(nu, "terrainImmune");
    if (nu.alive && effect.status && !spared) nu = addStatus(nu, effect.status, undefined, effect.pow);
