    // Whatever an aura granted last time is dropped first: what is true now is
    // decided only by who is standing where now.
    const own = (u.statuses || []).filter((st) => !st.aura);
    if (!u.alive) return own.length === (u.statuses || []).length ? u : { ...u, statuses: own };
    let nu = { ...u, statuses: own };
